/* Brand-led presentation views. Markup remains real, accessible HTML. */
window.MAX_PRESENTATION={create({D,R,ref,level,img,badge,zoomButton,esc,C,S,I}){
  const A=window.MAX_AMBASSADOR;
  const wordmark=()=>'<span class="netbet-wordmark"><img src="assets/logo/logo.webp" alt="NetBet" width="1200" height="247"><em>MAX</em></span>';
  const completeWardrobe=o=>o?.garments?`<section class="ensemble-record"><div><span class="eyebrow">The complete ensemble</span><h3>Every layer has a role.</h3></div><dl>${[o.familyId==='member'?'Waistcoat silhouette':'Coat & silhouette','Waistcoat & neckwear','Trousers','Footwear','Accessories & emblem'].map((name,i)=>`<div><dt>${name}</dt><dd>${esc(o.garments[i])}</dd></div>`).join('')}</dl></section>`:'';
  const campaignFrame=(c,preview=false)=>S.sceneFrame(c,preview);
  const blueArtwork=(cls='',eager=false)=>`<img class="${cls}" src="assets/images/intro-max-blue.webp" alt="Max, the silver-haired gentleman in his navy and red coat, welcomes you against an illuminated blue MAX backdrop." width="1672" height="941" loading="${eager?'eager':'lazy'}" decoding="async">`;
  const playIcon='<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M8 4.5v15l12-7.5z"/></svg>';
  const uiIcon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({game:'<path d="M7 7h10l4 10-3 2-4-4h-4l-4 4-3-2zM7 10v4M5 12h4M16 11h.1M18 13h.1"/>',gift:'<path d="M3 9h18v4H3zM5 13v8h14v-8M12 9v12"/><path d="M12 9C2 9 6 0 12 9c6-9 10 0 0 0z"/>',progress:'<path d="M5 20v-7h3v7zM11 20V8h3v12zM17 20V3h3v17z"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6z"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',bell:'<path d="M5 17h14l-2-4V8a5 5 0 0 0-10 0v5zM10 21h4"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',star:'<path d="m12 2 3 6 7 1-5 5 1 8-6-4-6 4 1-8-5-5 7-1z"/>'})[name]||''}</svg>`;
  const introTiers=()=>`<div class="intro-tier-strip" aria-label="A selection of official loyalty tiers">${['bronze','silver','gold','emerald','amethyst','diamond'].map(slug=>{const l=level(slug);return `<a href="#detail/${slug}">${badge(l)}<span>${l.name}</span></a>`;}).join('')}</div>`;
  const introMotion=()=>{const m=D.introVideo;return `<div class="intro-product-hero intro-embedded-player" id="intro-film"><video id="intro-video" hidden tabindex="0" controls preload="none" playsinline poster="assets/images/intro-max-navy.webp" aria-label="Max: ${esc(m.name)}"><source src="${esc(m.src)}" type="video/mp4">${m.captions?`<track default kind="captions" src="${esc(m.captions)}" srclang="en" label="English">`:''}Your browser cannot play this video. <a href="${esc(m.src)}">Download the clip</a>.</video><div class="intro-video-cover"><img src="assets/images/intro-max-navy.webp" alt="Full-length Max in his navy coat, red waistcoat and ivory trousers, welcoming visitors against the dark NetBet MAX campaign background." width="1672" height="941" loading="lazy"><div class="intro-product-copy"><span class="eyebrow">NETBET LOYALTY PROGRAMME</span><h3>Meet NetBet <i>Max</i></h3><p>Max is your guide on the NetBet loyalty journey. He helps you understand XP, levels and rewards, every step of the way.</p><a class="button" href="#wardrobe">Discover the programme <span aria-hidden="true">›</span></a><div class="intro-hero-perks"><span>${uiIcon('progress')}<span>Play and<br>earn XP</span></span><span>${uiIcon('shield')}<span>Explore<br>your level</span></span><span>${uiIcon('gift')}<span>Discover<br>your rewards</span></span></div>${introTiers()}</div><button type="button" class="intro-product-watch max-film-trigger" data-intro-watch aria-label="Play Max’s character film"><span class="max-play-ring">${playIcon}</span><span class="max-film-trigger-label">Max explains<span>Watch the character film</span></span></button></div></div><p class="intro-video-status" role="status" hidden></p>`;};
  const loyaltyExample=()=>`<section class="wrap section-spaced intro-loyalty" id="intro-example" aria-labelledby="intro-example-title"><div class="section-head"><div><span class="eyebrow">Motion / Character film</span><h2 id="intro-example-title">The ranks in <i>motion.</i></h2></div><div class="intro-example-tools"><p>Your Max, inside the NetBet experience. Select the play icon to meet him in motion.</p><a class="text-link" href="#story/motion">Explore the character film →</a><div class="intro-device-switch" role="group" aria-label="Loyalty page preview size"><button type="button" data-intro-device="desktop" aria-pressed="true">Desktop</button><button type="button" data-intro-device="mobile" aria-pressed="false">Mobile</button></div></div></div><div class="intro-site-preview" id="intro-site-preview"><div class="intro-product-header"><span class="intro-demo-menu" aria-hidden="true">▣</span><span class="intro-netbet-logo"><img src="assets/logo/logo.webp" alt="NetBet" width="1200" height="247"></span><div class="intro-demo-account"><span>${uiIcon('shield')} Standard</span><span>${uiIcon('gift')} Demo account</span>${uiIcon('search')}${uiIcon('bell')}${uiIcon('user')}</div></div><div class="intro-product-body"><aside class="intro-product-sidebar" aria-label="Example page sections"><div class="intro-demo-categories"><span>${uiIcon('game')} Casino</span><span>◉ <span>Sports</span></span></div><span class="intro-sidebar-heading">Promotions</span><a href="#landing">Bonus offers</a><a href="#landing">All promotions <span>›</span></a><a href="#wardrobe">${uiIcon('progress')} Missions</a><a href="#wardrobe">${uiIcon('gift')} Rewards</a><a href="#intro/example" aria-current="page">${uiIcon('star')} MAX</a><span class="intro-sidebar-heading">More games</span><div class="intro-demo-links"><span>♧ <span>Live Casino</span></span><span>◉ <span>Lotto</span></span><span>♤ <span>Poker</span></span><span>◷ <span>Live Betting</span></span><span>♧ <span>Virtual Sports</span></span></div><span class="intro-sidebar-heading">Recent games</span><div class="intro-demo-links"><span>✦ <span>New</span></span><span>☆ <span>Popular</span></span><span>▤ <span>Slots</span></span></div></aside><div class="intro-product-main"><div class="intro-product-title"><div><h3>Loyalty Program</h3><p>Play, earn XP, level up and discover your rewards.</p></div><a href="#story">Learn more <span aria-hidden="true">ⓘ</span></a></div>${introMotion()}<div class="intro-product-benefits"><a href="#wardrobe"><span class="intro-benefit-symbol">${uiIcon('progress')}</span><span><strong>Earn XP from your favourite games</strong><small>Follow your progress through the programme.</small></span></a><a href="#wardrobe"><span class="intro-benefit-symbol">${uiIcon('shield')}</span><span><strong>Level up and discover new benefits</strong><small>Explore the rewards at every level.</small></span></a><button type="button" data-intro-watch><span class="intro-benefit-symbol">${uiIcon('gift')}</span><span><strong>Max is always by your side</strong><small>A familiar guide to your loyalty journey.</small></span></button></div></div></div></div><div class="intro-example-caption"><span>Concept demonstration only. NetBet layout with the Max character.</span><a class="text-link" href="#landing">Explore all landing pages ↗</a></div></section>`;
  const promotionAnnotations=[
    {title:'Calm, familiar and friendly',side:'right',row:9,noLine:true,text:'Max has a calm, approachable expression designed to feel friendly and easy to remember.',finish:'Swept silver hair, black rectangular glasses and a neatly groomed white beard give him a clear, consistent identity.',role:'These features keep Max recognizable at different sizes, from full campaign artwork to smaller assistant moments.'},
    {title:'Coat & silhouette',x:42,y:31,side:'left',row:22,text:'A navy textured long tailcoat establishes the formal silhouette.',finish:'Dark navy texture with vivid red piping and red lining.',role:'The long cut keeps Max immediately recognizable in a promotional composition.'},
    {title:'Waistcoat & shirt',x:52,y:34,side:'left',row:43,text:'A red brocade waistcoat sits over a crisp white shirt.',finish:'Tonal red pattern, gold-coloured buttons and a bright white centre.',role:'The high-contrast layers keep the outfit readable at campaign scale.'},
    {title:'Bow tie & NB',x:60.7,y:21.9,side:'right',row:21,text:'A red bow tie completes the neckline while the gold NB mark identifies Max.',finish:'Red bow tie, white collar and gold-coloured NB lettering.',role:'Brand recognition remains on the chest without adding a rank shield.'},
    {title:'Cuff & open gesture',x:78,y:35,side:'right',row:43,text:'White cuffs and brown fastenings frame an open, welcoming hand gesture.',finish:'White cuff, red-edged sleeve and warm brown button detail.',role:'The open palms leave the promotion feeling invitational and clear.'},
    {title:'Ivory trousers',x:53,y:64,side:'left',row:69,text:'High-waisted ivory trousers lengthen and brighten the lower silhouette.',finish:'Warm ivory tailoring with a clean pressed front.',role:'The pale trousers create separation from the navy coat and dark background.'},
    {title:'Oxford shoes',x:54,y:91,side:'right',row:84,text:'Brown-and-white Oxford shoes complete the coordinated ensemble.',finish:'Two-tone brown and ivory leather appearance with dark lacing.',role:'The footwear repeats the warm and light tones used through the outfit.'}
  ];
  const promotionDetail=(index=0)=>{const a=promotionAnnotations[index]||promotionAnnotations[0],n=promotionAnnotations.slice(0,promotionAnnotations.indexOf(a)+1).filter(item=>!item.noLine).length;return `<div><span class="eyebrow">${a.noLine?'Character identity':`Detail ${String(n).padStart(2,'0')}`} / Promotion wardrobe</span><h2>${a.title}</h2><p>${a.text}</p>${a.noLine?'':`<button type="button" class="text-link" data-image="build-front" data-focus="${a.x},${a.y}">Inspect this detail <span aria-hidden="true">↗</span></button>`}</div><dl class="annotation-properties"><div><dt>Appearance & finish</dt><dd>${a.finish}</dd></div><div><dt>Promotional role</dt><dd>${a.role}</dd></div><div><dt>Artwork</dt><dd>Build-front · navy, red and ivory full-character study.</dd></div></dl>`;};
  const promotionStudy=()=>`<section class="wrap section-spaced rule intro-promotion-study" aria-labelledby="promotion-study-title"><div class="section-head"><div><span class="eyebrow">Promotion wardrobe / Build-front</span><h2 id="promotion-study-title">Navy, red<br><i>and ivory.</i></h2></div></div><div class="annotated-stage promotion-annotated" aria-label="Annotated navy, red and ivory promotional outfit"><div class="detail-figure">${I.artwork('build-front','',true)}</div><svg class="annotation-lines" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${promotionAnnotations.map((a,i)=>{if(a.noLine)return '';const x=20+a.x*.6,sx=a.side==='left'?17.5:82.5,elbow=a.side==='left'?23:77;return `<path data-promotion-line="${i}" class="${i===0?'selected-line':''}" d="M ${sx} ${a.row} L ${elbow} ${a.row} L ${x} ${a.y}"></path>`;}).join('')}</svg>${promotionAnnotations.map((a,i)=>{const bx=a.noLine?0:20+(a.buttonX??a.x)*.6,by=a.buttonY??a.y,n=promotionAnnotations.slice(0,i+1).filter(item=>!item.noLine).length;return `<button type="button" class="annotation-label ${a.side}${a.noLine?' annotation-label-text-only':''}" style="top:${a.row}%" data-promotion-annotation="${i}" aria-pressed="${i===0}"><span class="eyebrow">${a.noLine?'Character identity':String(n).padStart(2,'0')}</span><strong>${a.title}</strong><small>${a.finish}</small></button>${a.noLine?'':`<button type="button" class="hotspot" data-promotion-annotation="${i}" aria-label="Detail ${n}: ${a.title}" aria-pressed="${i===0}" style="--x:${a.buttonX??a.x};--desktop-x:${bx};left:calc(var(--desktop-x)*1%);top:${by}%">${n}</button>`}`;}).join('')}</div><div class="detail-controls"><button type="button" class="button secondary" data-image="build-front">View complete look & zoom ↗</button></div><div class="annotation-inspector" id="promotion-annotation-panel" aria-live="polite">${promotionDetail(0)}</div></section>`;
  const introDiscovery=()=>`<section class="wrap section-spaced intro-discovery"><div class="section-head"><div><span class="eyebrow">Explore the collection</span><h2>Meet every side of Max.</h2></div><p>A first look at his expressions, full-body gestures and campaign worlds. Each card opens the complete section.</p></div><div class="intro-discovery-grid"><article class="intro-discovery-group faces"><div class="intro-discovery-title"><span class="eyebrow">Character Build</span><h3>Face & expression</h3></div><div class="intro-discovery-cards">${[['face-front','Front view'],['face-three-quarter','Central three-quarter view'],['face-profile','Side view']].map(([id,title])=>`<a class="intro-discovery-card" href="#build/${id}">${S.artwork(id)}<strong>${title}</strong><span>Open character study →</span></a>`).join('')}</div></article><article class="intro-discovery-group poses"><div class="intro-discovery-title"><span class="eyebrow">Body language</span><h3>Pose & gesture</h3></div><div class="intro-discovery-cards">${[['gold','family-gold','Open-palm welcome'],['sapphire','family-sapphire','A considered explanation']].map(([levelId,poseId,title])=>`<a class="intro-discovery-card" href="#poses/${poseId}">${C.character(levelId,'',false,false)}<strong>${title}</strong><span>Open pose study →</span></a>`).join('')}</div></article><article class="intro-discovery-group landings"><div class="intro-discovery-title"><span class="eyebrow">In the experience</span><h3>Landing pages</h3></div><div class="intro-discovery-cards">${[['welcome','The blue gallery'],['salon-ensemble','The grand salon']].map(([id,title])=>{const c=A.campaigns.find(c=>c.id===id);return `<a class="intro-discovery-card" href="#landing/${id}">${S.artwork(c.scene)}<strong>${title}</strong><span>Open landing page →</span></a>`;}).join('')}</div></article></div></section>`;
  const guideIntroduction=()=>`<section class="wrap section-spaced rule intro-guide-showcase"><div class="section-head"><div><span class="eyebrow">Ask Max / In-product guide</span><h2>A helpful face,<br><i>right when it matters.</i></h2></div><p>Two supplied concepts introduce Max as a visible site guide: a browsable help centre and a conversational assistant.</p></div><div class="intro-guide-grid">${[['guide-max-overview','Help centre overview','Questions, topics and shortcuts in one clear starting point.'],['guide-max-chat','Guided conversation','A full conversation view with suggested questions and direct routes into NetBet Max.']].map(([id,title,copy],i)=>`<article class="intro-guide-card"><figure>${img(id,'',i===0)}${zoomButton(id)}</figure><div><span class="eyebrow">Concept ${String(i+1).padStart(2,'0')}</span><h3>${title}</h3><p>${copy}</p></div></article>`).join('')}</div></section>`;
  function intro(){return `<div class="intro-view brand-intro intro-refreshed"><section class="ambassador-hero intro-selected-hero" aria-labelledby="intro-title"><div class="ambassador-hero-art"><div class="campaign-aura" aria-hidden="true"></div><div class="intro-hero-duo">${I.artwork('build-front','intro-hero-image',true)}${I.artwork('build-profile','intro-hero-image intro-hero-profile',true)}<span class="intro-hero-closeup">${S.artwork('face-profile','',true)}</span><span class="intro-hero-closeup">${S.artwork('face-front','',true)}</span>${I.artwork('build-gothic','intro-hero-image',true)}${I.artwork('family-gold','intro-hero-image',true)}</div></div><div class="ambassador-hero-copy"><span class="hero-concept-label">CONCEPT</span><span class="eyebrow">The NetBet MAX ambassador</span>${wordmark()}<h1 id="intro-title">Meet Max.<br><span>Your personal<br>guide.</span></h1><p>One recognizable character. A complete wardrobe.<br>A gesture for every moment.</p><div class="hero-character-title"><span>Character</span><strong>Calm. Familiar. Friendly.</strong></div><p class="hero-disclaimer"><strong>Concept demonstration only.</strong> The character can be further developed and scaled across additional journeys, formats and interactions.</p><div class="button-row"><a class="button" href="#landing">See the landing pages <span aria-hidden="true">→</span></a><a class="text-link" href="#wardrobe/gold">Explore the wardrobe ↗</a></div></div></section><div class="marquee-note"><span>Welcome</span><span>Guide</span><span>Explain</span><span>Present</span><span>Always Max</span></div>
    ${loyaltyExample()}
    <div class="intro-collection-content">${promotionStudy()}${guideIntroduction()}<div class="wrap">${C.cardGrid('intro',{title:'Four looks. One Max.',eyebrow:'The selected wardrobe / 4 models · 8 views'})}</div>${introDiscovery()}<section class="wrap section-spaced"><div class="section-head"><div><span class="eyebrow">Character + message + offer</span><h2>Max, in the experience.</h2></div><a class="text-link" href="#landing">Explore all landing pages ↗</a></div><div class="intro-landing-stack">${campaignFrame(A.campaigns.find(c=>c.id==='temple-ensemble'),true)}${campaignFrame(A.campaigns.find(c=>c.id==='emerald'),true)}${S.suppliedPreview('supplied-7')}</div></section></div></div>`;}
  const landing=(id='welcome',device='desktop')=>S.landing(id,device);
  function sources(){const supplied=R.filter(r=>r.origin==='Supplied reference');return `<section class="section-spaced rule" id="sources"><div class="source-layout"><div><span class="eyebrow">The reference record</span><h2>Artwork first.<br><i>Interpretation labelled.</i></h2><p class="fine-note" style="margin-top:23px">${supplied.reduce((n,r)=>n+r.files.length,0)} supplied image files resolve to ${supplied.length} unique references. Duplicate filenames remain in the inventory. Earlier conversation images, fifteen family wardrobes, campaign environments and expression studies are included, with their origin clearly marked.</p><a class="button secondary" style="margin-top:24px" href="assets/documents/netbet-max-brief.pdf" target="_blank" rel="noopener">Read the character brief ↗</a><br><a class="text-link" href="assets/reference-manifest.json" target="_blank" rel="noopener">Open the image manifest ↗</a></div><dl class="source-list"><div><dt>The same character</dt><dd>Original Max artwork defines the silver hair, glasses, white beard, expression and long-legged silhouette. The fifteen family wardrobe images are generated proposals, using the clothing photographs for garments only. Each official rank has a complete presentation; sibling ranks share one image and garment design while the exact chest emblem changes. Original sources remain unchanged in the archive.</dd></div><div><dt>Complete ensembles</dt><dd>The newest cream-trouser reference informs the Regency look as a whole. The black/burgundy reference informs floral borders, layers, fastenings and the chain. Navy/gold and royal-blue references establish other coordinated directions. Costume interpretations are not claims of historical authenticity or verified production construction.</dd></div><div><dt>Corrected archive reading</dt><dd>In the original archive, Diamond has a blue waistcoat and silver-grey cravat; Icon has a pale waistcoat; Elite Pro has green layers and gold-coloured neckwear. These source studies are preserved. The active family proposals introduce coordinated cream, blue, burgundy, green, checked and pinstriped trousers; sibling ranks now share the same complete outfit.</dd></div><div><dt>Badges and branding</dt><dd><a href="${D.figma}" target="_blank" rel="noopener">Figma / Player Badges</a> supplies all 28 separate emblems and level names. The NB mark identifies Max; the chest shield identifies the tier. Shared gemstone families retain their core as the wings change. The active wardrobe uses the exact exported PNG as an image-relative chest layer. The same layer stays attached in full views, close-ups and zoom. NB and cuff N marks remain rendered parts of the costume. The foundation shields are separate designs; gemstone families have two, three or four ranks.</dd></div><div><dt>Landing-page palette and offers</dt><dd>The supplied blue landing-page screenshot defines the visual direction. Benefit categories and the Reserve £20 casino bonus, 10× wagering and £100 maximum win were checked on the <a href="${A.source}" target="_blank" rel="noopener">official NetBet Max page</a> on ${A.sourceChecked}. The ten page examples are creative proposals, not personalised or claimable offers. Current official terms take precedence.</dd></div><div><dt>Story and motion</dt><dd>The supplied brief establishes a mature, helpful, calm host with dry wit. Dialogue and assistant interactions here are proposed. Two supplied character films present Max and introduce the Bronze rank. Playback stays visitor-controlled. Reduced-motion preferences disable automatic interface motion.</dd></div></dl></div><div class="open-items"><h3>Coverage & production notes</h3><ul><li><strong>Wardrobe coverage:</strong> all 28 levels are presented with 15 complete family designs and their exact official chest emblems. Original and newly generated artwork are labelled separately.</li><li><strong>Character Build:</strong> twelve face studies, four body-angle studies and ten campaign environments extend the collection as labelled proposals.</li><li><strong>Character films:</strong> the main film is on the Introduction page and the shorter film remains in the Character motion section.</li><li><strong>Production approval:</strong> the small rendered NB/N marks, final garment construction and embroidery specifications if garment construction is commissioned.</li><li><strong>Brief review note:</strong> the supplied PDF asks for compliance review of wardrobe changes tied to loyalty progression. This remains a character and creative-direction presentation.</li></ul></div></section>`;}
  const filmRanks=()=>`<div class="film-ranks-heading"><div><span class="eyebrow">The progression / Six visual milestones</span><h3>A rank to recognise. A story to follow.</h3></div><p>Max introduces each milestone with its own colour and emblem.</p></div><div class="film-ranks" aria-label="Rank and XP concept from the supplied reference">${[['bronze','Bronze','0 – 10,000 XP','#eda45d'],['silver','Silver','10,000 – 50,000 XP','#c6d8e7'],['gold','Gold','50,000 – 125,000 XP','#f6d85b'],['emerald','Elite Pro','125,000 – 200,000 XP','#3be78e'],['amethyst','Emblematic','200,000+ XP','#d17aff'],['diamond','Legendary','Final milestone','#65d6ff']].map(([slug,name,xp,color])=>`<a class="film-rank" href="#detail/${slug}" style="--rank-color:${color}" aria-label="${name}: ${xp}. Explore the ${level(slug).name} character design.">${badge(level(slug))}<strong>${name}</strong><span>${xp}</span><small>Explore character ↗</small></a>`).join('')}</div><p class="film-reference-note">Rank names and XP ranges follow the supplied creative reference. Legendary has no XP threshold specified. Select a badge to explore its matching character design.</p>`;
  const filmDirection=()=>`<section class="film-direction" aria-labelledby="film-direction-title"><div class="section-head"><div><span class="eyebrow">Character direction</span><h3 id="film-direction-title">One familiar guide, in every frame.</h3></div><a class="text-link" href="#intro/example">See Max in the website →</a></div><div class="film-detail-grid"><article><span class="film-detail-number">01 / Presence</span><h4>A calm introduction</h4><p>Silver hair, black glasses and a warm expression keep Max recognisable. An open palm welcomes the viewer before a measured pointing gesture directs attention to the rank.</p></article><article><span class="film-detail-number">02 / Identity</span><h4>The emblem stays in place</h4><p>Keep the rank emblem on the same chest position throughout the shot. Leave the face, hands and badge clearly visible as Max introduces each milestone.</p></article><article><span class="film-detail-number">03 / Dialogue</span><h4>A clear, helpful voice</h4><p>Short, direct lines give each message room to land. Dialogue captions should sit below the action, clear of Max’s face and emblem.</p></article></div><div class="film-script"><span class="eyebrow">Proposed opening line</span><blockquote>“Let’s take a look at your rank. I’ll show you where you are and what comes next.”</blockquote><p>Creative direction for the next edit. This proposed dialogue and its captions are not included in the supplied films.</p></div></section>`;
  const filmPoster=m=>`<div class="character-film-player" data-character-film="${esc(m.id)}"><video hidden tabindex="0" controls preload="none" playsinline poster="assets/images/intro-max-blue.webp" aria-label="Max: ${esc(m.name)}"><source src="${esc(m.src)}" type="video/mp4">${m.captions?`<track default kind="captions" src="${esc(m.captions)}" srclang="en" label="English">`:''}Your browser cannot play this video. <a href="${esc(m.src)}">Download the clip</a>.</video><button type="button" class="character-film-poster max-film-trigger" data-character-watch="${esc(m.id)}" aria-label="Play ${esc(m.name)}">${blueArtwork()}<span class="character-film-copy"><small>NETBET MAX / CHARACTER FILM</small><strong>Max<br>explains…</strong><span>${esc(m.name)}</span></span><span class="max-play-ring">${playIcon}</span></button></div><p class="character-film-status" data-film-status="${esc(m.id)}" role="status" hidden></p>`;
  return {intro,landing,sources,completeWardrobe,campaignFrame,promotionDetail,filmPoster,filmRanks,filmDirection};
}};
